// build-wfc-bundle.mjs — bundles the vendored CommonJS WFC port into one ES module
// for the browser runtime. The vendored sources are NEVER modified; this script
// only wraps them in module closures. Re-run after any vendor update:
//
//   node tools/worldgen/build-wfc-bundle.mjs
//
// Output: game/js/worldgen/vendor/wfc.bundle.mjs  (ESM, `export const WFC`)
// Sources: game/js/worldgen/vendor/wavefunctioncollapse/*.js (pristine, MIT)
import { readFileSync, writeFileSync } from 'fs';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(here, '..', '..');
const srcDir = join(repoRoot, 'game', 'js', 'worldgen', 'vendor', 'wavefunctioncollapse');
const outPath = join(repoRoot, 'game', 'js', 'worldgen', 'vendor', 'wfc.bundle.mjs');

// dependency order: leaves first
const ORDER = ['random-indice', 'model', 'simple-tiled-model', 'overlapping-model', 'index'];

function wrap(name) {
  const body = readFileSync(join(srcDir, name + '.js'), 'utf8');
  // Each file is a CommonJS module: top-level `require`, `module`, `exports`.
  // Wrap it so those names resolve to the bundle-local registry instead of globals.
  return (
    `__wfc_registry['./${name}'] = (function (module, exports, require) {\n` +
    body.replace(/module\.exports\s*=/, 'module.exports =') +
    `\nreturn module.exports;\n})({ exports: {} }, {}, __wfc_require);\n`
  );
}

let out = `// wfc.bundle.mjs — GENERATED by tools/worldgen/build-wfc-bundle.mjs — DO NOT EDIT.
// Bundles the vendored wavefunctioncollapse 2.1.0 port
// (https://github.com/kchapelier/wavefunctioncollapse, MIT, Kevin Chapelier)
// which is itself a port of https://github.com/mxgmn/WaveFunctionCollapse (MIT, Maxim Gumin).
// Pristine sources live in game/js/worldgen/vendor/wavefunctioncollapse/.
// Rebuild: node tools/worldgen/build-wfc-bundle.mjs
const __wfc_registry = {};
function __wfc_require(path) {
  if (!__wfc_registry[path]) throw new Error('[worldgen] WFC bundle: unknown module ' + path);
  return __wfc_registry[path];
}
`;

for (const name of ORDER) out += wrap(name);

out += `export const WFC = __wfc_registry['./index'];\n`;
out += `export default WFC;\n`;

writeFileSync(outPath, out);
console.log('[worldgen] wrote', outPath, `(${(out.length / 1024).toFixed(1)} KB)`);
